import React from "react";
import InteractiveMap from "./InteractiveMap";

export default function App() {
  return (
    <main className="min-h-screen bg-gray-100">
      {/* Red title bar */}
      <header className="bg-[#84000a] text-white text-center py-4 shadow-md">
        <h1 className="text-2xl font-bold tracking-wide">Spring Fling Map</h1>
      </header>

      {/* Interactive Map */}
      <section className="p-4">
        <InteractiveMap />
      </section>
    </main>
  );
}
